// --- Dimensions ---
width = 16;           // Width of the hook
total_height = 55;    // Total height of the backplate
thickness_base = 6;   // Thickness of the part against the wall
hook_depth = 35;      // How far it sticks out from the wall
hook_tip_height = 25; // Height of the tip of the hook relative to bottom

// --- Screw Dimensions (M3 Flat Head) ---
screw_hole_diam = 3.5;    // Clearance for M3
screw_head_diam = 6.8;    // Head diameter (slightly loose for fit)
screw_head_depth = 3.0;   // Depth of the conical head
screw_pos_z = total_height - 12; // Position from bottom

module hook_body() {
    // 1. The Backplate (Vertical Spine)
    hull() {
        // Top of spine
        translate([0, thickness_base/2, total_height - width/2])
            rotate([90, 0, 0])
            cylinder(d=width, h=thickness_base, center=true);

        // Bottom junction
        translate([0, thickness_base/2, width/2])
            rotate([90, 0, 0])
            cylinder(d=width, h=thickness_base, center=true);
    }

    // 2. The Hook Arm (Curved section)
    hull() {
        // Connection to spine
        translate([0, thickness_base/2, width/2])
            rotate([90, 0, 0])
            cylinder(d=width, h=thickness_base, center=true);

        // The "Elbow" (forward and slightly down/up)
        translate([0, hook_depth * 0.4, 5])
            rotate([90, 0, 0])
            cylinder(d=width, h=thickness_base, center=true);
    }

    hull() {
        // The "Elbow"
         translate([0, hook_depth * 0.4, 5])
            rotate([90, 0, 0])
            cylinder(d=width, h=thickness_base, center=true);

        // The Tip
        translate([0, hook_depth, hook_tip_height])
            rotate([90, 0, 0]) // Rotate cylinder to match orientation
            cylinder(d=width, h=thickness_base, center=true);
    }

    // Add a ball tip for aesthetic/safety
    translate([0, hook_depth, hook_tip_height])
        sphere(d=width*0.8); // Slightly smaller than width looks nice
}

module screw_hole() {
    translate([0, -10, screw_pos_z]) // Star far back (y=-10)
    rotate([-90, 0, 0]) { // Pointing towards +Y
        // The thru-hole
        cylinder(d=screw_hole_diam, h=50);

        // The countersink
        // Calculate position: We want the head flush with Y=0 (the back) NO, flush with the FRONT face.
        // The screw goes FROM the front TO the wall (at Y=0).
        // Wait, standard coordinates:
        // Wall is generally considered the mounting surface.
        // My model has the back surface at Y=0.
        // The screw enters from positive Y, goes towards negative Y (into wall).

        // Face of the hook at the screw position roughly at Y = thickness_base.
        // Actually, since we used center=true for the cylinders in Y, the back face is at -thickness_base/2.

        // Let's adjust coordinate system so Back Face is Z=0 or Y=0? 
        // Currently: Cylinders are centered on Y = thickness_base/2. Thickness is `thickness_base`.
        // So Front face is at `thickness_base`. Back face is at 0.

        // So screw head starts at Y = thickness_base (Front face)
        // And tapers down into the material.

        translate([0, 0, 10 + thickness_base - screw_head_depth]) 
            cylinder(d1=screw_hole_diam, d2=screw_head_diam, h=screw_head_depth + 0.1);

        // Clearance for head above surface (if any)
        translate([0, 0, 10 + thickness_base])
            cylinder(d=screw_head_diam, h=20);
    }
}

// Assemble
translate([0, 0, 0]) { // Centered on X
    difference() {
        hook_body();
        screw_hole();
    }
}
