// --- Dimensions ---
width = 16;           // Width of the hook (X axis)
thickness = 6;        // Thickness of the hook profile (Y axis)
total_height = 55;    // Total height (Z axis)

// --- Screw Dimensions (M3 Flat Head / Countersunk) ---
screw_hole_diam = 3.4;    
screw_head_diam = 7.0;    // Standard M3 countersunk head is ~6mm, slightly loose for easy fit
screw_head_depth = 2.5;   // Depth of the cone
screw_pos_z = total_height - 12; 

module hook_shape() {
    // Define the spine and hook as a sequence of points [y, z]
    // The X thickness is handled by the hull/sphere diameter
    // The Y thickness is handled by offsetting or using cylinders

    // We construct the shape by hulling sequential spheres/cylinders

    points = [
        [0, total_height - width/2], // Top of backplate
        [0, 20],                     // Middle of backplate
        [0, width/2],                // Bottom of backplate
        [5, 0],                      // Curve start (forward, down)
        [20, 2],                     // Bottom of curve
        [32, 10],                    // Tip approach
        [35, 20]                     // Tip
    ];

    // Define the diameter at each point for a tapered look
    // Thicker at the base (load bearing), slightly thinner at tip
    diameters = [
        width, // Top
        width, // Mid
        width, // Base junction
        width, // Curve start
        width, // Bottom
        width * 0.85, // Tapering
        width * 0.85  // Tip
    ];

    union() {
        for (i = [0 : len(points) - 2]) {
            hull() {
                // Point A
                translate([0, points[i][0], points[i][1]])
                    rotate([0, 90, 0])
                    // Use a cylinder flattened in Y to create the "Plate" effect
                    // but smoothly transitioning.
                    // Actually, simple cylinders oriented X create a rounded side profile.
                    // To get a flat back (Y=0), we need to be careful.
                    // Creating a flat back with hulls of cylinders is hard.

                    // Better approach:
                    // Use resize() or scale() on spheres/cylinders?
                    // Let's stick to the previous robust method but iterated.
                    // To ensure flat back at Y=0, the "spine" points have Y=0,
                    // and we extrude/hull from Y=0 to Y=thickness.

                    // Let's go back to: Backplate is a block. Hook is an appendage.
                    // It's stronger and prints cleaner.

                    // Placeholder for loop intersection
                    cube(0.1); 
            }
        }

        // REVISED GEOMETRY APPROACH:
        // 1. Backplate: Rounded Rectangle
        // 2. Hook Arm: Smooth Hull Chain

        // Backplate
        hull() {
            translate([-width/2, 0, width/2])
                cube([width, thickness, total_height - width]);

            // Top Round
            translate([-width/2, thickness/2, total_height - width/2])
                rotate([0, 90, 0])
                cylinder(r=thickness/2, h=width);

            // Bottom Round
            translate([-width/2, thickness/2, width/2])
                rotate([0, 90, 0])
                cylinder(r=thickness/2, h=width);
        }

        // Hook Arm
        // We hull from the bottom of the backplate to the tip.

        // Start of arm (embedded in backplate)
        hull() {
             translate([0, thickness/2, width/2]) // Center of bottom backplate area
                rotate([0, 90, 0])
                cylinder(d=width, h=1, center=true); // Reference point

             translate([0, thickness + 2, 0]) // Curve out
                rotate([0, 90, 0])
                cylinder(d=width, h=1, center=true);
        }

        hull() {
             translate([0, thickness + 2, 0])
                rotate([0, 90, 0])
                cylinder(d=width, h=1, center=true);

             translate([0, 20, 0]) // Bottom of J
                rotate([0, 90, 0])
                cylinder(d=width, h=1, center=true);
        }

        hull() {
             translate([0, 20, 0])
                rotate([0, 90, 0])
                cylinder(d=width, h=1, center=true);

             translate([0, 32, 10]) // Before Tip
                rotate([0, 90, 0])
                cylinder(d=width*0.9, h=1, center=true);
        }

        hull() {
             translate([0, 32, 10])
                rotate([0, 90, 0])
                cylinder(d=width*0.9, h=1, center=true);

             translate([0, 35, 20]) // Tip
                sphere(d=width*0.9);
        }
    }
}

// Re-write using a cleaner single-hull-chain function
module sleek_hook() {

    // Define the path of the hook (Y, Z)
    // Relative to the FRONT face of the backplate (Y=thickness)
    path = [
        [0, 10],   // Embed in base
        [5, 0],    // Start curve
        [20, 0],   // Bottom
        [32, 12],  // Up
        [35, 22]   // Tip
    ];

    // Backplate
    difference() {
        hull() {
            translate([-width/2, 0, width/2])
                cube([width, thickness, total_height - width]);

            // Top caps
            translate([-width/2, thickness/2, total_height - width/2])
                rotate([0, 90, 0])
                cylinder(r=thickness/2, h=width);

            // Bottom cap
            translate([-width/2, thickness/2, width/2])
                rotate([0, 90, 0])
                cylinder(r=thickness/2, h=width);
        }
        // No subtract here, subtract hole later
    }

    // Arm
    // Hull from Base to P0, P0 to P1, etc.

    // Transition from Base Rectangle to Arm Cylinder
    hull() {
        translate([-width/2, 0, width/2]) // Bottom section of base
            cube([width, thickness, 10]); 

        translate([0, thickness + path[0][0], path[0][1]])
            rotate([0, 90, 0])
            cylinder(d=width, h=0.1, center=true);
    }

    for (i = [0 : len(path)-2]) {
        hull() {
            translate([0, thickness + path[i][0], path[i][1]])
                rotate([0, 90, 0])
                cylinder(d=width, h=0.1, center=true);

            translate([0, thickness + path[i+1][0], path[i+1][1]])
                rotate([0, 90, 0])
                if (i == len(path)-2) {
                    // Last point is a sphere tip
                    sphere(d=width); // Rotate doesn't affect sphere but good for consisteny
                } else {
                    cylinder(d=width, h=0.1, center=true);
                }
        }
    }

    // Explicit Tip Sphere to be sure
    translate([0, thickness + path[len(path)-1][0], path[len(path)-1][1]])
        sphere(d=width);
}

module final_assembly() {
    difference() {
        sleek_hook();

        // Screw Hole
        translate([0, thickness + 1, screw_pos_z]) // Start slightly continuously
        rotate([90, 0, 0]) {
            // CounterSink logic
            // Head is at the surface (z=0 in local screw coords => y=thickness+1 in world)
            // Screw goes down into -Z (World -Y)

            // Head cylinder (clearance above flush)
            translate([0,0,-2]) cylinder(d=screw_head_diam, h=10);

            // Cone
            // We want the rim of the cone to be at Y=thickness.
            // Local Z = -1 (since origin is thickness+1)
            // Let's reset origin to Y=thickness

        }

        // Simple Screw Cutout
        translate([0, thickness, screw_pos_z]) 
        rotate([90, 0, 0]) {
            // Countersink Cone: Starts at z=0, goes down into material (-z)
            // d1 is tip, d2 is rim.
            // OpenSCAD cylinder(h): from 0 to h. 
            // So we need to rotate/translate properly.

            // Shaft (infinite)
            translate([0,0,-20]) cylinder(d=screw_hole_diam, h=40);

            // Cone
            // Rim at z=0 (Surface). Tip at z = -screw_head_depth.
            translate([0,0, -screw_head_depth])
                cylinder(d1=screw_hole_diam, d2=screw_head_diam, h=screw_head_depth);

            // Head Clearance (air)
            cylinder(d=screw_head_diam, h=10);
        }
    }
}

final_assembly();
